// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testFuzz_property(address callee, bytes memory data) public {
        vm.assume(callee != address(this));
        vm.assume(callee != address(c));
        vm.assume(callee != msg.sender);
        Reverter reverter = new Reverter();
        callee = address(reverter);
        address actor = address(0x12345);
        vm.deal(actor, 0);
        vm.prank(actor);
        bool ok;
        try c.forward(callee, data) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
contract Reverter {
    fallback() external payable { revert(); }
    receive() external payable { revert(); }
}
